@Test
fun evaluateTiming_tooSoon_reportsExactMinutesRemaining() {
    val mostRecentDose = DoseLog(
        id = 1,
        profileId = 1,
        medicationId = 1,
        givenAtEpochMillis = 0L,
        doseAmount = "5ml",
    )
    // Candidate is exactly 10 minutes before the 60-minute mark.
    val candidate = 50 * 60_000L
    val result = DoseTimingCalculator.evaluateTiming(candidate, mostRecentDose, 60)
    assertTrue(result is DoseTimingResult.TooSoon)
    assertEquals(10L, (result as DoseTimingResult.TooSoon).minutesRemaining)
}
